// contexts/YearFilterContext.js
'use client';

import { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';

const YearFilterContext = createContext();

export function YearFilterProvider({ children }) {
  const [selectedYear, setSelectedYear] = useState(null);
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());
  const [availableYears, setAvailableYears] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchYears = async () => {
      try {
        // Récupérer l'année courante depuis le backend
        const yearRes = await axios.get('/api/current-year');
        setCurrentYear(yearRes.data.year);
        setSelectedYear(yearRes.data.year);
        
        // Récupérer les années disponibles
        const yearsRes = await axios.get('/api/available-years');
        setAvailableYears(yearsRes.data);
      } catch (error) {
        console.error("Erreur lors du chargement des années:", error);
        setSelectedYear(new Date().getFullYear());
      } finally {
        setLoading(false);
      }
    };
    
    fetchYears();
  }, []);

  const value = {
    selectedYear,
    currentYear,
    availableYears,
    loading,
    setSelectedYear,
    isCurrentYear: (year) => year === currentYear,
    filterByYear: (data, yearField = 'annee') => {
      return selectedYear ? data.filter(item => item[yearField] == selectedYear) : data;
    }
  };

  return (
    <YearFilterContext.Provider value={value}>
      {children}
    </YearFilterContext.Provider>
  );
}

export function useYearFilter() {
  const context = useContext(YearFilterContext);
  if (!context) {
    throw new Error('useYearFilter must be used within a YearFilterProvider');
  }
  return context;
}